import type { Workspace } from './workspace-model';

export const FormDefinitionStatusKeyToLabel = {
  'Draft': 'Draft',
  'Published': 'Published',
  'Retired': 'Retired'
} as const;
export type FormDefinitionStatusKey = keyof typeof FormDefinitionStatusKeyToLabel;

export interface FormDefinition {
  /**
   * @displayName Form Definition ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  name1: string;
  /**
   * @displayName Current Version Number
   * @validationRule Required for create/update operations
   */
  currentVersionNumber: number;
  /**
   * @displayName Description
   * @validationRule Required for create/update operations
   */
  description: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: FormDefinitionStatusKey;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _FormDefinition = 'FormDefinition' as const;